import numpy as np
import scipy
import control as ct
import matplotlib.pyplot as plt
from scipy.optimize import brentq
s=ct.tf('s');G=1/(s+1)
controllers={'P4':ct.tf([4],[1]),'PI11':(s+1)/s,'PI21':(2*s+1)/s}
a=(3-np.sqrt(5))/2;b=(3+np.sqrt(5))/2
c=(np.sqrt(5)-1)/(2*np.sqrt(5));h=(3/np.sqrt(5)-1)/2
def error(name,t):
    if name=='P4':return .2+.8*np.exp(-5*t)
    if name=='PI11':return np.exp(-t)
    return c*np.exp(-a*t)+(1-c)*np.exp(-b*t)
def command(name,t):
    if name=='P4':return .8+3.2*np.exp(-5*t)
    if name=='PI11':return np.ones_like(t,dtype=float)
    return 1-h*np.exp(-a*t)+(1+h)*np.exp(-b*t)
def settling(name,A,eps):
    if eps>=A:return 0.
    residual=.2*A if name=='P4' else 0.
    if eps<=residual:return np.inf
    return brentq(lambda t:A*error(name,t)-eps,0,100,xtol=1e-12)
def u_peak(name,A):
    # P4 decreases; PI11 constant; PI21 has a single interior minimum.
    if name=='PI21':
        tmin=np.log(b*(1+h)/(a*h))/(b-a)
        return A*max(2.,1.,abs(command(name,tmin)))
    return A*(4. if name=='P4' else 1.)
contracts=[('A',1.,.02,3.,8.),('B',.25,.06,1.2,2.),('C',1.,.02,1.5,8.),('D',1.,.02,.5,8.)]

